// NNOV Clinic Suite: deterministic fictional data, browser-local workflows.
const DEMO_DAY=27;
const STORAGE_KEY='nnov-clinic-suite-v2';
const ROLES={owner:{name:'Руководитель',views:NAV.map(x=>x[0])},admin:{name:'Администратор',views:['overview','schedule','patients','care','tasks','training','results']},coordinator:{name:'Координатор',views:['overview','plans','care','tasks','training','results']}};
NAV.splice(7,0,['care','shield','Сопровождение']);ROLES.owner.views=NAV.map(x=>x[0]);
let role='owner',suiteDrawer=null,selectedStaff='Анна',quizState=null,financeFocus='all',storageAvailable=true;
const CHOICE={considering:'Обсуждение',agreed:'Решение принято',paused:'Пауза',completed:'Завершён'};
const sum=(rows,fn)=>rows.reduce((a,x)=>a+fn(x),0);
const percent=(a,b)=>b?Math.round(a/b*100):0;
function serviceFixtures(key){return key==='implant'?[
 {id:'consult',name:'Первичная консультация',price:2500,payroll:750,materials:150,external:0,hours:.5},
 {id:'hygiene',name:'Профессиональная гигиена',price:6500,payroll:1950,materials:850,external:0,hours:1},
 {id:'surgery',name:'Хирургический этап',price:45000,payroll:13500,materials:17000,external:3000,hours:1.5},
 {id:'ortho',name:'Ортодонтический приём',price:28000,payroll:8400,materials:2000,external:9000,hours:1.5},
 {id:'prosthetics',name:'Ортопедический этап',price:42000,payroll:12600,materials:null,external:12000,hours:1.5}
]:[
 {id:'consult',name:'Консультация специалиста',price:3000,payroll:900,materials:100,external:0,hours:.5},
 {id:'gastro',name:'Гастроскопия',price:7000,payroll:2100,materials:1800,external:0,hours:.5},
 {id:'colono',name:'Колоноскопия',price:10000,payroll:3000,materials:2400,external:0,hours:1},
 {id:'complex',name:'Комплексное исследование',price:18000,payroll:5400,materials:null,external:5000,hours:1},
 {id:'ultra',name:'Ультразвуковое исследование',price:4000,payroll:1200,materials:200,external:0,hours:.5}
];}
function suiteSeed(key){
 const d=seed(key),services=serviceFixtures(key),endo=key==='endo';d.services=services;d.costVerified={};d.monthLedger=[];
 for(let day=1;day<=26;day++)for(let j=0;j<services.length;j++){
  const s=services[j],qty=(day+j*3)%5+1+(j<2?2:0),amount=qty*s.price;
  d.monthLedger.push({id:`L-${day}-${j}`,day,service:s.id,qty,amount,paid:amount-((day%9===0&&j===2)?s.price:0),source:'Модель МИС',type:'base'});
 }
 CONFIG[key].base.forEach((row,r)=>row.forEach((state,col)=>{if(state==='done'){const s=services[(r+col)%services.length];d.monthLedger.push({id:`TODAY-${r}-${col}`,day:27,service:s.id,qty:1,amount:s.price,paid:s.price,source:'Модель МИС',type:'base'});}}));
 d.plans=Array.from({length:endo?14:18},(_,i)=>{
  const choices=['considering','agreed','agreed','paused','completed','agreed'];const choice=choices[i%6];
  const sids=endo?['consult','complex','consult']:['consult','surgery','prosthetics'];
  const stages=sids.map((sid,k)=>{const s=services.find(x=>x.id===sid),qty=(!endo&&i%3===0&&k>0)?2:1;let status=(k===0||choice==='completed')?'done':'pending';return {id:'S'+(k+1),name:endo?['Первичная консультация','Исследование по назначению врача','Обсуждение результатов'][k]:['Диагностический этап','Хирургический этап','Ортопедический этап'][k],service:sid,qty,amount:s.price*qty,status,paid:status==='done'?s.price*qty:0,doneDay:status==='done'?Math.min(26,12+i%8+k):null,appointment:null};});
  if(i===2&&!endo){stages[1].status='scheduled';stages[1].appointment={day:27,room:3,col:2};}
  if(i===5){stages[1].status='scheduled';stages[1].appointment={day:28,room:0,col:4};}
  return {id:'P-'+(101+i),patient:(endo?'E-':'D-')+(701+i),choice,doctor:(endo?'Врач E-':'Врач D-')+(1+i%3),coordinator:['Мария','Анна'][i%2],version:1,doctorApproved:true,medicalConsent:choice==='completed',discussed:choice!=='considering',pauseReason:choice==='paused'?'Пациент попросил связаться позже':'',nextContact:i%3===0?'Сегодня, до 14:00':'28 октября, до 12:00',notes:[],stages,log:[(stages[0].doneDay-1)+' окт · План подготовлен врачом',stages[0].doneDay+' окт · Выполнен диагностический этап']};
 });
 d.managerTasks=[{id:'M-101',title:'Уточнить решение по плану P-101',kind:'plan',target:'P-101',admin:'Мария',state:'new',due:'Сегодня, 14:00',note:''},{id:'M-102',title:'Сверить число визитов между источниками',kind:'quality',target:'visits',admin:'Анна',state:'new',due:'Сегодня, 16:00',note:''}];
 d.calls=Array.from({length:12},(_,i)=>({id:'C-'+(201+i),admin:ADMINS[i%3],patient:d.items[i%d.items.length].id,reason:['Не предложено другое время','Не уточнён следующий шаг','Запись завершена','Недостаточно информации об услуге'][i%4],quality:[58,72,95,65][i%4],reviewed:i%4===2,task:false,lesson:i%4===0?'alternatives':'nextstep',excerpt:i%4===0?'Пациент: «На вечер есть время?»\nАдминистратор: «У этого специалиста только днём».\nПациент: «Тогда позже решу».':i%4===1?'Пациент: «Хорошо, я подумаю».\nАдминистратор: «Звоните, если решите».':i%4===2?'Администратор уточнил удобное время, согласовал запись и повторил детали визита.':'Пациент задал административный вопрос по услуге. Ответ не найден в базе знаний. Вопрос остался без ответственного.',nextCheck:false}));
 d.lessons={};d.care=Array.from({length:6},(_,i)=>({id:'R-'+(301+i),patient:d.plans[i].patient,kind:endo?(i%2===0?'Подготовка к исследованию':'Контакт после визита'):(i%2===0?'Назначенный контрольный визит':'Пауза между этапами'),assigned:ADMINS[i%3],due:i<3?'Сегодня':'28 октября',sent:i===1,ack:i===1,question:i===2,escalated:false,closed:false,notes:[]}));
 d.tickets=[{id:'F-01',title:'Долго ждали ответа о переносе',patient:d.items[0].id,status:'new',owner:'Ольга'},{id:'F-02',title:'Нужно уточнить состав стоимости',patient:d.plans[0].patient,status:'new',owner:'Мария'},{id:'F-03',title:'Благодарность за сопровождение',patient:d.plans[1].patient,status:'closed',owner:'Анна'}];
 d.fixed=[{name:'Аренда и содержание',amount:endo?280000:360000},{name:'Административная команда',amount:endo?330000:420000},{name:'Маркетинг',amount:endo?180000:250000},{name:'Сервисы и прочие расходы',amount:120000}];
 d.quality={visits:false,sync:false};d.scenario={price:0,materials:0,visits:0};d.events=[{type:'note',text:'Загружен демонстрационный месяц. Все показатели смоделированы.',time:'Начало демо'}];
 d.resources=Array.from({length:CONFIG[key].rooms},(_,i)=>({name:CONFIG[key].roomLabel+' '+(i+1),team:endo?'Врач, медсестра, оборудование':'Врач, ассистент, кресло',status:i===1?'Плановое обслуживание после смены':'Доступен по смене'}));return d;
}
function restoreDemo(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const saved=JSON.parse(raw);if(saved.schema===2&&saved.db?.implant?.plans&&saved.db?.endo?.quality){Object.assign(DB,saved.db);clinic=CONFIG[saved.clinic]?saved.clinic:'implant';role=ROLES[saved.role]?saved.role:'owner';return;}}}catch{storageAvailable=false;}DB.implant=suiteSeed('implant');DB.endo=suiteSeed('endo');}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify({schema:2,db:DB,clinic,role}));storageAvailable=true;}catch{storageAvailable=false;}}
function logEvent(text,type='note'){data().events.unshift({text,type,time:'В демо · '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})});data().events=data().events.slice(0,60);}
function svc(id){return data().services.find(x=>x.id===id)||data().services[0];}
function materialCost(s){return s.materials===null?(data().costVerified[s.id]??null):s.materials;}
function unitCost(s){const m=materialCost(s);return m===null?null:s.payroll+m+s.external;}
function planTotal(p){return sum(p.stages,s=>s.amount);}
function planDone(p){return sum(p.stages,s=>s.status==='done'?s.amount:0);}
function planPaid(p){return sum(p.stages,s=>s.paid);}
function allLedger(){const rows=data().monthLedger.slice();for(const p of data().plans)for(const s of p.stages)if(s.status==='done')rows.push({id:p.id+'-'+s.id,day:s.doneDay,service:s.service,qty:s.qty,amount:s.amount,paid:s.paid,source:p.id,type:'plan'});for(const x of data().items)if(x.state==='attended')rows.push({id:'REC-'+x.id,day:27,service:clinic==='endo'?'colono':'hygiene',qty:1,amount:cfg().avg,paid:x.payment,source:x.id,type:'recovery'});return rows;}
function financials(){const rows=allLedger(),revenue=sum(rows,x=>x.amount),paid=sum(rows,x=>x.paid),known=rows.filter(x=>unitCost(svc(x.service))!==null),cost=sum(known,x=>unitCost(svc(x.service))*x.qty),covered=sum(known,x=>x.amount),fixed=sum(data().fixed,x=>x.amount);return {rows,revenue,paid,cost,covered,fixed,contribution:covered-cost,complete:known.length===rows.length,coverage:percent(covered,revenue),balance:sum(rows,x=>Math.max(0,x.amount-x.paid)),services:sum(rows,x=>x.qty)};}
function planCounts(){const plans=data().plans;return {active:plans.filter(p=>!['completed','paused'].includes(p.choice)).length,paused:plans.filter(p=>p.choice==='paused').length,considering:plans.filter(p=>p.choice==='considering').length,total:sum(plans,planTotal),done:sum(plans,planDone),paid:sum(plans,planPaid)};}
function qualityChecks(){const unknown=data().services.filter(s=>unitCost(s)===null);return [{id:'visits',title:'Сверка числа визитов',ok:data().quality.visits,desc:`Модель МИС: ${utilization().done} состоявшихся визитов сегодня. Модель аналитики: ${utilization().done+(data().quality.visits?0:2)}. Нужна проверка определения и статусов.`,action:'Зафиксировать сверку в демо'},{id:'cost',title:'Полнота прямых расходов',ok:unknown.length===0,desc:unknown.length?`Нет подтверждённой стоимости материалов: «${unknown[0].name}». Полный финансовый результат не рассчитывается.`:'По всем услугам демонстрационные прямые расходы заполнены.',action:'Заполнить расходы'},{id:'sync',title:'Актуальность статусов оплат',ok:data().quality.sync,desc:data().quality.sync?'Модель источника обновлена в текущем демо-сценарии.':'В модели финансового источника задержка 40 минут. Уведомление об оплате может прийти позже визита.',action:'Смоделировать обновление'},{id:'ids',title:'Связность идентификаторов',ok:true,desc:'Услуги, планы и оплаты связаны по идентификаторам. Персональные данные пациентов не используются.',action:''}];}
function availablePlanSlots(){const arr=[];for(const day of [27,28])for(let r=0;r<cfg().rooms;r++)for(let col=2;col<8;col++){
 if(day===27){if(col<6)continue;if(!['free','cancelled'].includes(cfg().base[r][col]))continue;if(data().items.some(x=>x.room===r&&x.col===col))continue;}
 if(day===28&&col%3===0)continue;
 if(data().plans.some(p=>p.stages.some(s=>s.appointment?.day===day&&s.appointment.room===r&&s.appointment.col===col&&s.status!=='pending')))continue;
 arr.push({day,room:r,col});}return arr.slice(0,12);}
function planSchedule(){const grid=cfg().base.map(r=>r.slice());for(const x of data().items)if(['booked','attended'].includes(x.state))grid[x.room][x.col]=x.state==='attended'?'done-recovered':'recovered';for(const p of data().plans)for(const s of p.stages)if(s.appointment?.day===27&&['scheduled','done'].includes(s.status))grid[s.appointment.room][s.appointment.col]=s.status==='done'?'done-recovered':'recovered';return grid;}
schedule=planSchedule;
function roleViews(){return NAV.filter(x=>ROLES[role].views.includes(x[0]));}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${ROLES[role].name} / ${cfg().direction} / демо</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function render(){if(!ROLES[role].views.includes(view))view='overview';assistantObserve();persist();const c=counts();document.getElementById('clinicIcon').innerHTML=ic('clinic');document.getElementById('clinicSelect').value=clinic;document.getElementById('roleSelect').value=role;document.getElementById('roleName').textContent=ROLES[role].name+' клиники';document.getElementById('navigation').innerHTML=roleViews().map(([id,icon,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''} onclick="navigate('${id}')">${ic(icon)}${label}${id==='assistant'?`<span class="count">${assistantThread().unread||'✦'}</span>`:''}${id==='tasks'?`<span class="count">${c.tasks+data().managerTasks.filter(t=>t.state!=='done').length}</span>`:''}${id==='quality'&&!qualityChecks().every(q=>q.ok)?'<span class="count">!</span>':''}</button>`).join('');const funcs={overview,assistant:assistantPage,schedule:schedulePage,patients:patientsPage,plans:plansPage,economics:economicsPage,team:teamPage,training:trainingPage,care:carePage,tasks:tasksPage,results:resultsPage,quality:qualityPage,pilot:pilotPage};document.getElementById('main').innerHTML=`<div class="page-view">${funcs[view]()}</div><footer class="footer"><span class="source-note">${ic('shield')}Все данные вымышлены. Интеграции и ИИ имитируются. ${storageAvailable?'Прогресс сохраняется в этом браузере.':'Прогресс хранится до закрытия вкладки.'}</span><span>NNOV.RU · Клиника · v0.4</span></footer>`;renderAssistantDock();}
function changeRole(value){role=value;closeDrawer(false);closeModal();view='overview';filter='all';query='';render();toast('Рабочее место: '+ROLES[role].name);}
function dashboardSignals(){const p=data().plans.find(x=>x.choice==='considering');const x=data().items.find(x=>['new','contact'].includes(x.state));const q=qualityChecks().find(x=>!x.ok);const out=[];
 if(x)out.push({icon:'calendar',title:'Есть возможность вернуть пациента в запись',body:`${x.id} · ${x.kind} · ${cfg().roomLabel} ${x.room+1}, ${9+x.col}:00.`,source:'Расписание + обращение',button:'Разобрать',action:`openItem('${x.id}')`,badge:'Сегодня'});
 if(p&&role!=='admin')out.push({icon:'note',title:'По плану '+p.id+' не зафиксировано решение',body:`${p.patient} · координатор ${p.coordinator}. Следующий шаг: уточнить решение и причину паузы.`,source:'План лечения + история контактов',button:'Открыть план',action:`openPlan('${p.id}')`,badge:'Контакт'});
 if(role==='owner'&&q)out.push({icon:'shield',title:q.title,body:q.desc,source:'Проверка согласованности демо-данных',button:'Проверить',action:"navigate('quality')",badge:'Данные'});
 if(role!=='owner')out.push({icon:'book',title:'Короткая практика по следующему шагу',body:'Разобрать административную ситуацию и зафиксировать результат упражнения.',source:'Демо-разборы обращений',button:'Начать',action:"navigate('training')",badge:'Команда'});
 return out;}
function signalMarkup(s){return `<article class="signal"><span class="signal-mark ${s.icon==='shield'?'':'green'}">${ic(s.icon)}</span><div class="signal-body"><h3>${s.title}</h3><p>${s.body}</p><div class="source-link">Основание: ${s.source}</div></div><div class="signal-end"><span class="badge ${s.icon==='shield'?'orange':'neutral'}">${s.badge}</span><button class="link" onclick="${s.action}">${s.button} ${ic('arrow')}</button></div></article>`;}
function overview(){const f=financials(),u=utilization(),pc=planCounts(),c=counts();const owner=role==='owner';return heading(owner?'Клиника под управлением.':role==='admin'?'Сегодня у каждого обращения есть шаг.':'Сопровождение без потерянных этапов.','Демо-день 27 октября · Демонстрационный месяц: 1–27 октября 2026.',`<button class="btn" onclick="startTour()">${ic('play')}Сценарий презентации</button>`)+`<section class="metrics wide-metrics">${owner?metric('Выручка от оказанных услуг',money(f.revenue),'Модель месяца · по факту оказания','chart'):metric('Обращений к действию',c.active,'Текущая очередь пациентов','users')}${metric('Загрузка сегодня',u.pct+'<span class="unit">%</span>',`${u.occupied} из ${u.total} ч · свободно ${u.free} ч`,'calendar')}${metric(owner?'Активных планов':'Планов на сопровождении',pc.active,`${pc.considering} на обсуждении · ${pc.paused} на паузе`,'note')}${owner?metric('Маржинальный доход',f.complete?money(f.contribution):'Нужны данные',f.complete?'До постоянных расходов и налогов':`Расходы известны для ${f.coverage}% выручки`,'money',true):metric('Визиты из задач',c.attended,`${c.booked} записано · ${money(c.receipts)} оплат`,'check',true)}</section>
<div class="suite-grid"><div><section class="panel suite-hero"><div class="eyebrow">${ic('spark')} Ежедневный помощник</div><h2>${owner?'Три фокуса дня: пациенты, загрузка и достоверная экономика.':role==='admin'?'Начать с обращений, по которым ещё можно договориться о визите.':'Проверить решения пациентов и назначить следующий этап.'}</h2><p>${owner?`В текущем демо свободно ${u.free} ч, решений по планам ожидают ${pc.considering} пациентов. ${f.complete?'Прямые расходы заполнены. Можно анализировать экономику услуг.':'Перед выводом о прибыли нужно заполнить недостающие прямые расходы.'}`:'Сводка обновляется после действий в карточках. У каждого сигнала есть источник, следующий шаг и ответственный.'}</p><div class="actions"><button class="btn lime" onclick="openAssistant('Что сделать первым сегодня?')">Обсудить следующие шаги ${ic('arrow')}</button><span class="chip">${ic('shield')}Демо-ассистент · по данным клиники</span></div><button class="assistant-hero-link" onclick="navigate('assistant')">Открыть чат и сводку дня →</button><div class="mini-stats"><div><strong>${c.active}</strong><small>Обращений к действию</small></div><div><strong>${data().managerTasks.filter(t=>t.state!=='done').length}</strong><small>Управленческих задач</small></div><div><strong>${data().care.filter(x=>!x.closed).length}</strong><small>Ситуаций сопровождения</small></div></div></section><section class="panel space-top"><div class="panel-head"><div><h2>Приоритетные действия</h2><div class="sub">Сигнал → основание → ответственный → результат</div></div><span class="badge">Сегодня</span></div>${dashboardSignals().map(signalMarkup).join('')}</section></div><div><section class="panel panel-pad"><div class="eyebrow">Оказанные услуги / ₽</div><h2>Динамика демонстрационного месяца</h2>${trendChart()}<div class="trend-labels"><span>14 октября</span><span>27 октября</span></div><div class="status-line" style="margin-top:20px"><span>Получено оплат за месяц</span><strong>${money(f.paid)}</strong></div><div class="status-line"><span>Остаток по оказанным услугам</span><strong>${money(f.balance)}</strong></div><p class="method">Оплаты и оказанные услуги учитываются отдельно. Все суммы смоделированы.</p></section><section class="panel space-top"><div class="panel-head"><h2>Последние действия</h2><span class="event-count">${data().events.length}</span></div><div style="padding:0 23px 15px">${activityMarkup(4)}</div></section></div></div>${role==='owner'?`<h2 class="section-title">Рабочие модули</h2><div class="module-grid">${[['plans','note','Координатор лечения','Решение пациента, этапы, контакты и оплаты.'],['economics','money','Экономика услуг','Прямые расходы, маржинальный доход и сценарии.'],['team','users','Команда и обучение','Разбор обращений, база знаний и практика.']].map(([id,icon,title,desc])=>`<article class="module">${ic(icon)}<h3>${title}</h3><p>${desc}</p><button class="btn text" onclick="navigate('${id}')">Перейти ${ic('arrow')}</button></article>`).join('')}</div>`:''}`;}
function trendChart(){const rows=allLedger();const values=Array.from({length:14},(_,i)=>sum(rows.filter(x=>x.day===14+i),x=>x.amount));const max=Math.max(...values,1);const points=values.map((n,i)=>`${i*360/13},${110-n/max*90}`).join(' ');return `<svg class="trend-chart" viewBox="-5 0 370 125" role="img" aria-label="Вымышленная динамика выручки от оказанных услуг за 14 дней"><path d="M0 20H360M0 65H360M0 110H360" stroke="#e9ede2" fill="none"/><polygon points="0,115 ${points} 360,115" fill="#edf3e5"/><polyline points="${points}" stroke="#5f865e" stroke-width="2.5" fill="none"/>${values.map((n,i)=>`<circle cx="${i*360/13}" cy="${110-n/max*90}" r="3" fill="#5f865e"><title>${14+i} октября: ${money(n)}</title></circle>`).join('')}</svg>`;}
function activityMarkup(limit=12){return data().events.slice(0,limit).map(x=>`<div class="activity-row">${ic(x.type)}<div><p>${esc(x.text)}</p><small>${esc(x.time)}</small></div></div>`).join('');}
function plansPage(){const pc=planCounts();const plans=data().plans.filter(p=>filter==='all'||p.choice===filter);return heading('План лечения продолжается в действиях.','Врачебный план, решение пациента, следующий этап и фактические расчёты связаны в одной карточке.')+`<section class="metrics wide-metrics">${metric('Планов в работе',pc.active,`${pc.considering} ожидают решения`,'note')}${metric('На паузе',pc.paused,'Причина и следующий контакт','clock')}${metric('Выполнено по планам',money(pc.done),'Стоимость уже оказанных услуг','check')}${metric('Получено по планам',money(pc.paid),'Фактические оплаты в демо','money',true)}</section><div class="toolbar"><div class="tabs">${[['all','Все планы'],['considering','Обсуждение'],['agreed','В работе'],['paused','Пауза'],['completed','Завершены']].map(([id,t])=>`<button class="${filter===id?'active':''}" onclick="filter='${id}';render()">${t}</button>`).join('')}</div><span class="date-chip">${plans.length} планов</span></div><section class="panel"><div class="panel-head"><div><h2>Пациенты на сопровождении</h2><div class="sub">Коды и планы полностью вымышлены</div></div><span class="badge">Версии и история</span></div>${plans.map(p=>`<article class="plan-row"><div><h3>${p.patient} · ${p.id}</h3><p>${p.doctor} · координатор ${p.coordinator}</p><div class="plan-progress" aria-label="Выполнено ${p.stages.filter(s=>s.status==='done').length} из ${p.stages.length} этапов">${p.stages.map(s=>`<i class="${s.status==='done'?'done':s.status==='scheduled'?'scheduled':''}"></i>`).join('')}</div></div><div><span class="badge ${p.choice==='paused'?'orange':p.choice==='considering'?'neutral':'green'}">${CHOICE[p.choice]}</span><p style="margin-top:7px">${p.choice==='paused'?esc(p.pauseReason):p.choice==='completed'?'Все этапы выполнены':'Следующий контакт: '+p.nextContact}</p></div><div class="plan-amount">${money(planTotal(p))}<small>Полная стоимость плана<br>Выполнено: ${money(planDone(p))}</small></div><button class="btn sm" onclick="openPlan('${p.id}')">Открыть ${ic('arrow')}</button></article>`).join('')||'<div class="empty">Планов с таким статусом нет</div>'}</section><p class="presentation-note">Решение пациента по стоимости, врачебный план и медицинское согласие фиксируются отдельно. Полная стоимость плана не считается выручкой.</p>`;}
function showSuiteDrawer(type,id,title,body){lastFocus=document.activeElement;drawerId=null;suiteDrawer={type,id};document.getElementById('overlayRoot').innerHTML=`<div class="overlay" onclick="if(event.target===this)closeDrawer()"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawerTitle"><header class="drawer-head"><span>${title}</span><button class="circle-button" aria-label="Закрыть карточку" onclick="closeDrawer()">${ic('close')}</button></header><div class="drawer-content">${body}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.drawer-head .circle-button')?.focus(),0);}
function openPlan(id){const p=data().plans.find(p=>p.id===id);if(!p)return;showSuiteDrawer('plan',id,`Координатор / ${id}`,`<div class="pill-row"><span class="badge ${p.choice==='paused'?'orange':'green'}">${CHOICE[p.choice]}</span><span class="badge neutral">Версия ${p.version}</span><span class="badge neutral">Вымышленный пациент</span></div><h2 id="drawerTitle">${p.patient}<br>Следующий этап под контролем.</h2><p>План подготовлен ${p.doctor}. Координатор сопровождает исполнение и общение, медицинские назначения остаются за врачом.</p><dl class="detail-grid"><div><dt>Полная стоимость плана</dt><dd>${money(planTotal(p))}</dd></div><div><dt>Оказано услуг</dt><dd>${money(planDone(p))}</dd></div><div><dt>Получено оплат</dt><dd>${money(planPaid(p))}</dd></div><div><dt>Следующий контакт</dt><dd>${p.nextContact}</dd></div></dl><div class="drawer-section"><h3>Решение пациента и ответственность</h3><div class="field"><label for="planOwner">Координатор</label><select id="planOwner">${ADMINS.map(x=>`<option ${p.coordinator===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="planChoice">Решение по обсуждаемому плану</label><select id="planChoice" ${p.choice==='completed'?'disabled':''}>${Object.entries(CHOICE).filter(([key])=>key!=='completed'||p.choice==='completed').map(([key,v])=>`<option value="${key}" ${p.choice===key?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="pauseReason">Причина паузы / результат контакта</label><input id="pauseReason" maxlength="300" value="${esc(p.pauseReason)}" placeholder="Например: договорились связаться 28 октября"></div><button class="btn primary" onclick="savePlanDecision('${p.id}')">Сохранить решение</button><div class="demo-note space-top">План утверждён врачом в модели. Решение по стоимости не заменяет медицинское согласие.</div><label style="display:flex;gap:9px;align-items:flex-start;font-size:10px;line-height:1.8;margin-top:15px"><input type="checkbox" ${p.medicalConsent?'checked':''} onchange="togglePlanConsent('${p.id}',this.checked)">Отметка: медицинское согласие оформлено в клинике (демо). Подпись и документ здесь не создаются.</label></div><div class="drawer-section"><h3>Этапы плана</h3>${p.stages.map((s,i)=>`<article class="stage"><div class="stage-head"><div class="stage-item"><span class="stage-number ${s.status==='done'?'done':''}">${s.status==='done'?'✓':i+1}</span><div><h4>${s.name}</h4><p>${svc(s.service).name} · ${s.qty} ед.</p></div></div><span class="badge ${s.status==='done'?'green':s.status==='scheduled'?'orange':'neutral'}">${s.status==='done'?'Выполнен':s.status==='scheduled'?'Запланирован':'Ожидает'}</span></div><div class="stage-detail">Стоимость: <strong>${money(s.amount)}</strong> · Оплачено: ${money(s.paid)}${s.appointment?`<br>Запись: ${s.appointment.day} октября, ${9+s.appointment.col}:00 · ${cfg().roomLabel} ${s.appointment.room+1}`:''}${s.status==='done'?`<br>Факт оказания: ${s.doneDay} октября`:''}</div><div class="actions">${s.status==='pending'&&p.choice==='agreed'&&p.stages.slice(0,i).every(x=>x.status==='done')?`<button class="btn sm primary" onclick="schedulePlanStage('${p.id}','${s.id}')">Назначить этап</button>`:''}${s.status==='scheduled'&&s.appointment.day<=27?`<button class="btn sm primary" ${!p.medicalConsent||p.choice!=='agreed'?'disabled':''} onclick="completePlanStage('${p.id}','${s.id}')">Этап выполнен в демо</button>`:''}${s.status==='scheduled'?`<button class="btn sm" onclick="cancelPlanStage('${p.id}','${s.id}')">Отменить запись в демо</button>`:''}${s.status==='scheduled'&&s.appointment.day>27?'<span class="tiny-label">Будущий визит: факт выполнения ещё не отмечается</span>':''}${s.status==='done'&&s.paid<s.amount?`<button class="btn sm" onclick="payPlanStage('${p.id}','${s.id}')">Добавить оплату</button>`:''}</div>${s.status==='scheduled'&&!p.medicalConsent?'<span class="inline-warning">Перед отметкой выполнения нужна отметка о наличии медицинского согласия.</span>':''}</article>`).join('')}</div><div class="drawer-section"><h3>Контакт с пациентом</h3><div class="field"><label for="planNote">Комментарий координатора</label><textarea id="planNote" maxlength="500" placeholder="Что обсудили и о чём договорились"></textarea></div><button class="btn sm" onclick="savePlanNote('${p.id}')">Сохранить контакт</button><button class="btn sm" onclick="createManagerTask('plan','${p.id}','Связаться по плану ${p.id}','${p.coordinator}')">Задача координатору</button>${p.notes.map(n=>`<div class="note-card">${esc(n)}</div>`).join('')}</div><div class="drawer-section"><h3>История</h3><ol class="timeline">${p.log.slice().reverse().map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div>`);}
function savePlanDecision(id){const p=data().plans.find(x=>x.id===id),choice=p.stages.every(x=>x.status==='done')?'completed':document.getElementById('planChoice').value,reason=document.getElementById('pauseReason').value.trim();if(choice==='paused'&&!reason){toast('Укажите причину паузы');document.getElementById('pauseReason').focus();return;}p.choice=choice;p.pauseReason=reason;p.coordinator=document.getElementById('planOwner').value;p.discussed=true;p.log.push('27 окт · Решение: '+CHOICE[choice]+(reason?' · '+reason:''));if(choice==='agreed')data().managerTasks.filter(t=>t.kind==='plan'&&t.target===id).forEach(t=>t.state='done');logEvent(`${id}: зафиксировано решение пациента - ${CHOICE[choice]}`,'note');render();openPlan(id);toast('Решение сохранено');}
function togglePlanConsent(id,value){const p=data().plans.find(x=>x.id===id);p.medicalConsent=value;p.log.push('27 окт · '+(value?'Отмечено наличие медицинского согласия в демо':'Отметка о согласии снята'));persist();openPlan(id);}
function schedulePlanStage(pid,sid){const p=data().plans.find(x=>x.id===pid),s=p.stages.find(x=>x.id===sid),slots=availablePlanSlots();if(p.choice!=='agreed'||s.status!=='pending')return;if(!slots.length){toast('Свободных окон в демо не осталось');return;}showModal('Назначить следующий этап',`<p>${p.patient} · ${s.name}. В демо один этап занимает один часовой блок. Доступность ресурсов задана в модели.</p><div class="field"><label for="planSlot">Доступное время</label><select id="planSlot">${slots.map((a,i)=>`<option value="${i}">${a.day} октября, ${9+a.col}:00 · ${cfg().roomLabel} ${a.room+1}</option>`).join('')}</select></div><p>Согласование времени с пациентом имитируется этим действием.</p>`,`<button class="btn" onclick="closeModal()">Назад</button><button class="btn primary" onclick="confirmPlanSlot('${pid}','${sid}')">Подтвердить запись в демо</button>`);}
function confirmPlanSlot(pid,sid){const p=data().plans.find(x=>x.id===pid),s=p.stages.find(x=>x.id===sid);if(p.choice!=='agreed'||s.status!=='pending')return;const a=availablePlanSlots()[Number(document.getElementById('planSlot').value)];if(!a){toast('Окно уже занято');return;}s.appointment=a;s.status='scheduled';p.log.push(`27 окт · ${s.name}: запись на ${a.day} октября, ${9+a.col}:00`);logEvent(`${pid}: следующий этап записан на ${a.day} октября, ${9+a.col}:00`,'calendar');closeModal();render();openPlan(pid);toast('Запись появилась в плане и расписании');}
function cancelPlanStage(pid,sid){const p=data().plans.find(x=>x.id===pid),s=p.stages.find(x=>x.id===sid);if(s.status!=='scheduled')return;s.status='pending';s.appointment=null;p.log.push('27 окт · Запись на этап отменена в демо');logEvent(pid+': запись на этап отменена, окно освобождено','calendar');render();openPlan(pid);toast('Запись отменена в демо');}
function completePlanStage(pid,sid){const p=data().plans.find(x=>x.id===pid),s=p.stages.find(x=>x.id===sid);if(s.status!=='scheduled'||p.choice!=='agreed'||!p.medicalConsent||s.appointment.day>27)return;s.status='done';s.doneDay=27;if(p.stages.every(x=>x.status==='done'))p.choice='completed';p.log.push('27 окт · Выполнен этап: '+s.name);logEvent(`${pid}: подтверждено выполнение этапа. Оплата учитывается отдельно.`,'check');render();openPlan(pid);toast('Факт услуги отражён в экономике');}
function payPlanStage(pid,sid){const p=data().plans.find(x=>x.id===pid),s=p.stages.find(x=>x.id===sid);if(s.status!=='done'||s.paid>=s.amount)return;showModal('Оплата по выполненному этапу',`<p>${p.patient} · ${s.name}</p><div class="field"><label for="stagePayment">Подтверждённая сумма, ₽</label><input id="stagePayment" type="number" min="1" max="${s.amount-s.paid}" value="${s.amount-s.paid}"></div><p>Остаток: ${money(s.amount-s.paid)}. Внесение оплаты не меняет стоимость оказанных услуг.</p>`,`<button class="btn" onclick="closeModal()">Назад</button><button class="btn primary" onclick="confirmStagePayment('${pid}','${sid}')">Подтвердить оплату</button>`);}
function confirmStagePayment(pid,sid){const p=data().plans.find(x=>x.id===pid),s=p.stages.find(x=>x.id===sid),value=Number(document.getElementById('stagePayment').value);if(s.status!=='done'||!Number.isFinite(value)||value<=0||value>s.amount-s.paid){toast('Введите сумму в пределах остатка');return;}s.paid+=Math.round(value);p.log.push('27 окт · Получено '+money(value)+' по этапу '+s.name);logEvent(`${pid}: подтверждена оплата ${money(value)}`,'money');closeModal();render();openPlan(pid);toast('Оплата отражена в экономике и отчёте');}
function savePlanNote(id){const p=data().plans.find(x=>x.id===id),v=document.getElementById('planNote').value.trim();if(!v)return;p.notes.push(v);p.log.push('27 окт · Зафиксирован контакт с пациентом');logEvent(`${id}: координатор сохранил результат контакта`,'phone');render();openPlan(id);toast('Контакт сохранён');}
function economicsPage(){const f=financials(),unknown=data().services.find(s=>unitCost(s)===null);return heading('Видеть загрузку. Понимать экономику.','Демо-месяц 1–27 октября. Оказанные услуги, оплаты и затраты разделены.',`<button class="btn" onclick="exportFinance()">${ic('down')}Скачать расчёт CSV</button>`)+`<section class="metrics wide-metrics">${metric('Оказано услуг',f.services,'Единиц услуг в модели месяца','check')}${metric('Выручка по оказанным услугам',money(f.revenue),'Начислено за выполненные услуги','chart')}${metric('Получено оплат',money(f.paid),`Остаток: ${money(f.balance)}`,'money')}${metric('Маржинальный доход',f.complete?money(f.contribution):'Неполные данные',f.complete?'До постоянных расходов и налогов':`Прямые затраты известны для ${f.coverage}% выручки`,'money',true)}</section>${unknown?`<div class="insight-strip">${ic('alert')}<div><strong>Недостаточно данных для полного результата.</strong> Не заполнены материалы по услуге «${unknown.name}». <button class="hint-link" onclick="fillMissingCost('${unknown.id}')">Заполнить в демо</button></div></div>`:''}<section class="panel"><div class="panel-head"><div><h2>Экономика услуг</h2><div class="sub">Прямые расходы: оплата специалистов + материалы + внешние работы</div></div><span class="badge">Факт модели</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Услуга</th><th>Объём / выручка</th><th>Прямые расходы</th><th>Маржинальный доход</th><th></th></tr></thead><tbody>${data().services.map(s=>{const rows=f.rows.filter(x=>x.service===s.id),amount=sum(rows,x=>x.amount),qty=sum(rows,x=>x.qty),cost=unitCost(s),margin=cost===null?null:amount-qty*cost;return `<tr><td><strong>${s.name}</strong><small>Цена модели: ${money(s.price)}</small></td><td><strong>${money(amount)}</strong><small>${qty} единиц услуг</small></td><td><strong>${cost===null?'Не заполнены':money(qty*cost)}</strong><small>${cost===null?'Нет материалов':money(cost)+' на единицу'}</small></td><td class="margin-cell"><strong>${margin===null?'Не рассчитывается':money(margin)}</strong>${margin!==null?`<div class="cost-bar"><i style="width:${Math.max(0,percent(margin,amount))}%;background:#90ae74"></i><i style="flex:1;background:#e7d9bc"></i></div><small>${percent(margin,amount)}% от выручки услуги</small>`:'<small>Нужно подтвердить расходы</small>'}</td><td><button class="btn sm" onclick="openService('${s.id}')">Состав ${ic('arrow')}</button></td></tr>`;}).join('')}</tbody></table></div></section><div class="split space-top"><section class="panel panel-pad"><h2>От выручки к результату</h2><div class="finance-waterfall">${[['Оказанные услуги',f.revenue],['Прямые расходы',f.complete?f.cost:null],['Постоянные расходы',f.fixed],['Операционный результат',f.complete?f.contribution-f.fixed:null]].map(([t,v])=>`<div class="water-row"><span>${t}</span><div class="water-track"><i style="width:${v===null?0:Math.min(100,Math.abs(v)/f.revenue*100)}%"></i></div><strong>${v===null?'Нет данных':money(v)}</strong></div>`).join('')}</div><p class="method">Операционный результат рассчитан до налогов. Постоянные расходы заданы за месяц целиком; период 1–27 октября ещё не закрыт. Это промежуточная модель, не чистая прибыль.</p></section><section class="panel panel-pad"><h2>Постоянные расходы месяца</h2>${data().fixed.map(x=>`<div class="scenario-row"><span>${x.name}</span><strong>${money(x.amount)}</strong></div>`).join('')}<p class="method">Оплата врачей включена в прямые расходы. Административная команда учтена отдельно, двойного начисления нет.</p></section></div><section class="panel panel-pad space-top"><h2>Сценарий на текущей базе услуг</h2><div class="sub">База расчёта - объём услуг за 1–27 октября. Изменяется только сценарий, без пересчёта истории факта.</div><div class="calc-grid"><div>${[['price','Изменение цен, %',-20,30],['materials','Изменение стоимости материалов, %',-20,50],['visits','Изменение объёма услуг, %',-30,50]].map(([key,title,min,max])=>`<div class="field"><label for="scenario-${key}">${title}<span id="scenario-label-${key}">${data().scenario[key]}%</span></label><input id="scenario-${key}" type="range" min="${min}" max="${max}" value="${data().scenario[key]}" oninput="updateScenario('${key}',this.value)"></div>`).join('')}<p class="method">Модель считает неизменными оплату специалистам и внешние расходы на единицу услуги. Структура услуг и постоянные расходы сохраняются. Это допущения, а не прогноз.</p></div><div class="calc-result" id="scenarioResult">${scenarioMarkup()}</div></div></section><h2 class="section-title">Оказано, но ещё не оплачено</h2><section class="panel">${receivablesMarkup()}</section>`;}
function scenarioMarkup(){const f=financials(),p=data().scenario;if(!f.complete)return '<span class="tiny-label">Расчёт сценария</span><div class="big-number" style="font-size:25px">Сначала заполните расходы</div><small>Недостающие значения не заменяются предположением о нулевых затратах.</small>';const {revenue,cost,result}=scenarioValues();return `<span class="tiny-label">Операционный результат до налогов<br>при выбранных допущениях</span><div class="big-number">${money(result)}</div><span class="badge" style="background:#ffffff15;color:#cde1b7">Изменение: ${money(result-(f.contribution-f.fixed))}</span><hr><div class="calc-line"><span>Выручка сценария</span><b>${money(revenue)}</b></div><div class="calc-line"><span>Прямые расходы</span><b>${money(cost)}</b></div><div class="calc-line"><span>Постоянные расходы</span><b>${money(f.fixed)}</b></div><hr><small>Налоги, внедрение и возможное изменение постоянных расходов не учтены. Это не обещание результата.</small>`;}
function updateScenario(key,value){data().scenario[key]=Number(value);persist();document.getElementById('scenario-label-'+key).textContent=value+'%';document.getElementById('scenarioResult').innerHTML=scenarioMarkup();}
function openService(id){const s=svc(id),cost=unitCost(s);showModal(s.name,`<span class="badge">Экономика одной единицы / демо</span><div class="scenario-row"><span>Стоимость услуги</span><b>${money(s.price)}</b></div><div class="scenario-row"><span>Оплата специалистам</span><b>${money(s.payroll)}</b></div><div class="scenario-row"><span>Материалы</span><b>${materialCost(s)===null?'Не заполнены':money(materialCost(s))}</b></div><div class="scenario-row"><span>Внешние работы / лаборатория</span><b>${money(s.external)}</b></div><div class="scenario-row"><span>Маржинальный доход</span><b>${cost===null?'Нет данных':money(s.price-cost)}</b></div><p>Все значения демонстрационные. Постоянные расходы и налоги в эту сумму не входят.</p>`,cost===null?`<button class="btn primary" onclick="closeModal();fillMissingCost('${id}')">Заполнить материалы в демо</button>`:'');}
function fillMissingCost(id){const s=svc(id);showModal('Заполнить прямые расходы',`<p>${s.name}. Это моделирование ввода подтверждённого значения ответственным сотрудником.</p><div class="field"><label for="materialValue">Стоимость материалов на единицу, ₽</label><input id="materialValue" type="number" min="0" max="1000000" placeholder="Введите значение"></div><div class="field"><label for="costBasis">Основание значения</label><input id="costBasis" maxlength="150" value="Демонстрационный расчёт старшей медсестры"></div><p>После сохранения пересчитается экономика и проверка полноты данных. Для рабочего продукта потребуется фактический источник затрат.</p>`,`<button class="btn" onclick="closeModal()">Отмена</button><button class="btn primary" onclick="confirmMaterialCost('${id}')">Сохранить расход</button>`);}
function confirmMaterialCost(id){const field=document.getElementById('materialValue'),v=Number(field.value),basis=document.getElementById('costBasis').value.trim();if(field.value===''||!Number.isFinite(v)||v<0||v>1000000||!basis){toast('Введите сумму и основание');return;}data().costVerified[id]=Math.round(v);logEvent(`Заполнены материалы «${svc(id).name}»: ${money(v)}. Основание: ${basis}`,'money');closeModal();render();toast('Экономика и качество данных пересчитаны');}
function receivablesMarkup(){const rows=financials().rows.filter(x=>x.paid<x.amount);return rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Основание</th><th>Оказано</th><th>Оплачено</th><th>Остаток</th><th></th></tr></thead><tbody>${rows.slice(0,12).map(x=>`<tr><td><strong>${svc(x.service).name}</strong><small>${x.day} октября · ${x.source}</small></td><td>${money(x.amount)}</td><td>${money(x.paid)}</td><td>${money(x.amount-x.paid)}</td><td><button class="btn sm" onclick="settleLedger('${x.id}')">Зафиксировать оплату</button></td></tr>`).join('')}</tbody></table></div>${rows.length>12?'<div class="sub" style="padding:15px 23px">Показаны первые 12 записей. Полный перечень есть в CSV.</div>':''}`:'<div class="empty">Все оказанные услуги оплачены в демо</div>';}
function settleLedger(id){const row=allLedger().find(x=>x.id===id);if(!row||row.paid>=row.amount)return;if(row.type==='base'){data().monthLedger.find(x=>x.id===id).paid=row.amount;}else if(row.type==='plan'){for(const p of data().plans)for(const s of p.stages)if(p.id+'-'+s.id===id)s.paid=s.amount;}else{const x=find(row.source);x.payment=row.amount;}logEvent(`Подтверждена оплата остатка ${money(row.amount-row.paid)} по ${row.source}`,'money');render();toast('Остаток оплаты погашен в демо');}
function createManagerTask(kind,target,title,admin='Анна'){const existing=data().managerTasks.find(x=>x.kind===kind&&x.target===target&&x.state!=='done');if(existing){toast('Активная задача уже есть: '+existing.id);return existing;}const t={id:'M-'+(103+data().managerTasks.length),kind,target,title,admin,state:'new',due:'Сегодня, до конца смены',note:''};data().managerTasks.push(t);logEvent(`${t.id}: ${title}. Ответственный: ${admin}`,'tasks');render();toast('Задача создана: '+t.id);return t;}
function tasksPage(){const groups=[['todo','К действию'],['work','В процессе'],['done','Завершено']];const rows=[...data().items.filter(x=>x.task).map(x=>({id:x.id,title:x.title,admin:x.admin,state:['attended','closed'].includes(x.state)?'done':x.state==='booked'?'work':'todo',kind:'Обращение',due:x.due,action:`openItem('${x.id}')`})),...data().managerTasks.map(x=>({...x,state:x.state==='new'?'todo':x.state,kind:{plan:'План лечения',quality:'Качество данных',call:'Качество обращения',care:'Сопровождение',training:'Обучение'}[x.kind]||'Управление',action:`openManagerTask('${x.id}')`}))];return heading('У каждого действия есть владелец.','Обращения, планы лечения, качество данных и сопровождение в одной рабочей очереди.')+`<div class="insight-strip">${ic('tasks')}<div><strong>${rows.filter(x=>x.state!=='done').length} активных задач.</strong> Завершение управленческой задачи не создаёт визит, оплату или расход автоматически.</div></div><div class="team-board">${groups.map(([key,title])=>`<section class="team-column"><div class="column-title">${title}<span>${rows.filter(x=>x.state===key).length}</span></div>${rows.filter(x=>x.state===key).map(x=>`<button class="task-card" onclick="${x.action}"><span class="badge ${key==='done'?'green':'neutral'}">${x.id}</span><h3>${esc(x.title)}</h3><p>${esc(x.kind)}</p><div class="task-foot"><span class="person"><span class="avatar">${x.admin[0]}</span>${x.admin}</span><span>${esc(x.due)}</span></div></button>`).join('')||'<div class="empty">Задач пока нет</div>'}</section>`).join('')}</div>`;}
function openManagerTask(id){const t=data().managerTasks.find(x=>x.id===id);if(!t)return;const destinations={plan:'plans',quality:'quality',call:'team',care:'care',training:'training'};showModal(t.title,`<span class="badge">${t.id} · ${esc(t.due)}</span><div class="field space-top"><label for="managerOwner">Ответственный</label><select id="managerOwner">${ADMINS.map(x=>`<option ${x===t.admin?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="managerState">Статус</label><select id="managerState">${[['new','К действию'],['work','В процессе'],['done','Завершено']].map(([id,title])=>`<option value="${id}" ${t.state===id?'selected':''}>${title}</option>`).join('')}</select></div><div class="field"><label for="managerNote">Результат / комментарий</label><textarea id="managerNote" maxlength="500">${esc(t.note)}</textarea></div>`,`<button class="btn" onclick="closeModal();navigate('${destinations[t.kind]||'tasks'}')">Открыть раздел</button><button class="btn primary" onclick="saveManagerTask('${id}')">Сохранить задачу</button>`);}
function saveManagerTask(id){const t=data().managerTasks.find(x=>x.id===id);t.admin=document.getElementById('managerOwner').value;t.state=document.getElementById('managerState').value;t.note=document.getElementById('managerNote').value.trim();logEvent(`${id}: ${t.state==='done'?'задача завершена':t.state==='work'?'взята в работу':'обновлена'}`,'tasks');closeModal();render();toast('Задача сохранена');}
function openSlot(r,col){const p=data().plans.find(p=>p.stages.some(s=>s.appointment?.day===27&&s.appointment.room===r&&s.appointment.col===col&&s.status!=='pending'));if(p){openPlan(p.id);return;}openSlotBase(r,col);}
function schedulePage(){const base=scheduleBasePage();const reasons=['Не предложено другое время','Не уточнён следующий шаг','Недостаточно информации об услуге'];return base+`<h2 class="section-title">Неудовлетворённый спрос</h2><p class="period-note">Причины в отдельной выборке из 12 вымышленных разговоров. Это не статистика реальной клиники.</p><div class="demand-grid">${reasons.map(reason=>`<article class="demand-card"><span class="tiny-label">${reason}</span><strong>${data().calls.filter(x=>x.reason===reason).length}</strong><p>разговора в выборке</p></article>`).join('')}<article class="demand-card"><span class="tiny-label">Решение принято по плану</span><strong>${data().plans.filter(p=>p.choice==='agreed').length}</strong><p>пациентов на сопровождении</p></article></div><div class="split space-top"><section class="panel panel-pad"><h2>Ресурсы клиники</h2>${data().resources.map(r=>`<div class="resource-row"><div>${r.name}<small>${r.team}</small></div><span class="badge ${r.status.startsWith('Плановое')?'orange':'green'}">${r.status.startsWith('Плановое')?'Обслуживание после смены':'По расписанию'}</span></div>`).join('')}<p class="method">Демо показывает часовые блоки. В рабочем продукте состав ресурсов и длительность услуги задаёт клиника.</p></section><section class="panel panel-pad"><h2>Запланированные этапы</h2>${data().plans.flatMap(p=>p.stages.filter(s=>s.status==='scheduled').map(s=>({p,s}))).map(({p,s})=>`<div class="resource-row"><div>${p.patient} · ${s.name}<small>${s.appointment.day} октября, ${9+s.appointment.col}:00 · ${cfg().roomLabel} ${s.appointment.room+1}</small></div><button class="btn sm" onclick="openPlan('${p.id}')">План</button></div>`).join('')||'<div class="empty">Этапы пока не назначены</div>'}</section></div>`;}
function teamPage(){const calls=data().calls;return heading('Качество общения превращается в действие.','Отдельная выборка из 12 вымышленных разговоров. Разборы связаны с задачами и обучением.')+`<div class="team-strip">${ADMINS.map(name=>{const own=calls.filter(c=>c.admin===name),reviewed=own.filter(c=>c.reviewed).length,lessons=Object.values(data().lessons[name]||{}).filter(x=>x.passed).length;return `<article class="staff-card"><div class="person"><span class="avatar">${name[0]}</span><div><h3>${name}</h3><span class="tiny-label">Администратор</span></div></div><div class="staff-stats"><div><strong>${own.length}</strong><small>Разговоров в выборке</small></div><div><strong>${reviewed}/${own.length}</strong><small>Разобрано</small></div><div><strong>${lessons}/2</strong><small>Упражнений пройдено</small></div></div></article>`;}).join('')}</div><div class="toolbar"><div class="tabs">${[['all','Все разговоры'],['unreviewed','Нужен разбор'],['reviewed','Разобраны']].map(([id,t])=>`<button class="${filter===id?'active':''}" onclick="filter='${id}';render()">${t}</button>`).join('')}</div><button class="btn" onclick="navigate('training')">${ic('book')}Практика команды</button></div><section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Обращение</th><th>Сотрудник</th><th>Ситуация</th><th>Статус разбора</th><th></th></tr></thead><tbody>${calls.filter(c=>filter==='all'||(filter==='unreviewed'?!c.reviewed:c.reviewed)).map(c=>`<tr><td><strong>${c.id}</strong><small>Пациент ${c.patient} · демо-диалог</small></td><td>${c.admin}</td><td><strong>${c.reason}</strong><small>Оценка по модельному чек-листу: ${c.quality}/100</small></td><td><span class="badge ${c.reviewed?'green':'orange'}">${c.reviewed?'Разобран':'Проверить'}</span></td><td><button class="btn sm" onclick="openCall('${c.id}')">Разобрать ${ic('arrow')}</button></td></tr>`).join('')}</tbody></table></div></section><p class="presentation-note">Оценка не ставит диагноз сотруднику и не доказывает причинный эффект на продажи. В демо нет записи речи или распознавания реальных звонков.</p>`;}
function openCall(id){const c=data().calls.find(x=>x.id===id);showSuiteDrawer('call',id,'Качество / '+id,`<span class="badge ${c.reviewed?'green':'orange'}">${c.reviewed?'Разобран':'Нужна проверка'}</span><h2 id="drawerTitle">${c.reason}</h2><p>${c.admin} · ${c.patient} · полностью вымышленный диалог</p><div class="call-snippet">${esc(c.excerpt).replaceAll('\n','<br>')}</div><div class="drawer-section"><h3>Предложенный следующий шаг</h3><p class="method">${c.reason==='Запись завершена'?'Проверить полноту подтверждения и сохранить удачный пример.':c.lesson==='alternatives'?'Уточнить ограничения пациента по времени и предложить доступные варианты, соответствующие правилам клиники.':'Уточнить, какой вопрос остался, согласовать удобный следующий контакт и назначить ответственного.'}</p><div class="actions space-top"><button class="btn primary" onclick="reviewCall('${id}')">${c.reviewed?'Разбор сохранён':'Подтвердить разбор'}</button><button class="btn" onclick="createCallTask('${id}')">Задача сотруднику</button></div></div><div class="drawer-section"><h3>Практика по ситуации</h3><p class="method">Короткое упражнение для ${c.admin}. Завершение обучения само по себе не меняет конверсию или доходы.</p><button class="btn primary space-top" onclick="selectedStaff='${c.admin}';closeDrawer(false);navigate('training');startLesson('${c.lesson}')">${ic('book')}Открыть упражнение</button></div><div class="drawer-section"><h3>Проверка применения в работе</h3><p class="method">${c.nextCheck?'В демо руководитель зафиксировал повторную проверку.':'После упражнения нужен отдельный разбор нового обращения по тому же критерию.'}</p><button class="btn sm space-top" onclick="confirmPracticeCheck('${id}')">Зафиксировать проверку в демо</button></div>`);}
function reviewCall(id){const c=data().calls.find(x=>x.id===id);if(!c.reviewed){c.reviewed=true;logEvent(`${id}: ${c.admin}, подтверждён разбор обращения`,'phone');}render();openCall(id);toast('Разбор зафиксирован');}
function createCallTask(id){const c=data().calls.find(x=>x.id===id);createManagerTask('call',id,'Разобрать: '+c.reason,c.admin);c.task=true;persist();}
function confirmPracticeCheck(id){const c=data().calls.find(x=>x.id===id),done=data().lessons[c.admin]?.[c.lesson]?.passed;if(!done){toast('Сначала пройдите связанное упражнение');return;}if(!c.nextCheck){c.nextCheck=true;logEvent(`${id}: отмечена повторная проверка применения навыка в демо`,'check');}render();openCall(id);toast('Проверка сохранена, бизнес-показатели не подменяются');}
const KNOWLEDGE=[{id:'time',title:'Как предложить альтернативное время',text:'Уточнить допустимые дни и время. Проверить подходящие окна по правилам клиники. Предложить реальные варианты. При отсутствии окна зафиксировать запрос в листе ожидания. Не обещать недоступное время.'},{id:'next',title:'Как завершить разговор следующим шагом',text:'Уточнить, что осталось непонятным. Согласовать действие, ответственного и удобный срок следующего контакта. Повторить договорённость. Зафиксировать её в задаче.'},{id:'price',title:'Вопрос по стоимости и составу плана',text:'Использовать утверждённый клиникой прайс и актуальную версию плана. Разделять стоимость плана, выполненные услуги и оплаты. Медицинские вопросы и изменение назначения передавать врачу.'},{id:'prepare',title:'Вопрос по подготовке к исследованию',text:'Выдать актуальную инструкцию, утверждённую клиникой, и проверить получение. Вопросы по состоянию здоровья, препаратам и изменению схемы передавать медицинскому специалисту. Этот демо-справочник не содержит медицинских назначений.'}];
const LESSONS={alternatives:{title:'Помочь выбрать доступное время',desc:'Пациенту не подходит предложенное окно. Как сохранить возможность записи без неподтверждённых обещаний?',questions:[{q:'У нужного специалиста нет записи на удобный пациенту вечер. Какой следующий шаг?',options:['Сказать, что свободного времени нет, и завершить разговор','Уточнить ограничения, проверить подходящие альтернативы и предложить лист ожидания','Пообещать, что врач обязательно примет вне расписания'],correct:1,why:'Нужны реальные доступные варианты и согласованный следующий шаг. Обещания вне расписания требуют отдельного подтверждения.'},{q:'Пациент выбрал подходящее окно. Что зафиксировать?',options:['Только имя пациента','Сразу отметить визит состоявшимся','Согласованную запись, детали визита и результат контакта'],correct:2,why:'Запись, состоявшийся визит и оплата - разные события.'}]},nextstep:{title:'Согласовать понятный следующий шаг',desc:'Пациент сказал «я подумаю». Как понять причину и сохранить корректное сопровождение?',questions:[{q:'Что сделать после ответа «я подумаю»?',options:['Уточнить оставшийся вопрос и согласовать удобный следующий контакт','Поставить отказ без уточнений','Назначить лечение без согласования'],correct:0,why:'Важно понять вопрос пациента и договориться о следующем действии, сохраняя свободу его решения.'},{q:'Пациент задаёт медицинский вопрос, ответа на который нет в утверждённой инструкции. Как действовать?',options:['Составить ответ самостоятельно','Передать вопрос медицинскому специалисту и назначить ответственного за ответ','Игнорировать вопрос и предложить скидку'],correct:1,why:'Администратор организует получение ответа. Медицинское содержание подтверждает специалист.'}]}};
function trainingPage(){const done=Object.values(data().lessons[selectedStaff]||{}).filter(x=>x.passed).length;return heading('Короткая практика. Проверяемое применение.','Демонстрационное обучение по административным ситуациям. Знание проверяется отдельно от результата в работе.')+`<div class="toolbar"><div class="tabs">${ADMINS.map(n=>`<button class="${selectedStaff===n?'active':''}" onclick="selectedStaff='${n}';render()">${n}</button>`).join('')}</div><span class="badge green">${done}/2 упражнений пройдено</span></div><div class="split">${Object.entries(LESSONS).map(([id,l])=>{const result=data().lessons[selectedStaff]?.[id];return `<article class="lesson"><span class="badge ${result?.passed?'green':'neutral'}">${result?.passed?'Пройдено':result?'Нужна повторная практика':'2 вопроса · 3 минуты'}</span><h3>${l.title}</h3><p>${l.desc}</p>${result?`<div class="formula-box" style="margin:0 0 15px">Последний результат: ${result.score}/2<br>Попыток: ${result.attempts}</div>`:''}<button class="btn primary" onclick="startLesson('${id}')">${ic('book')}${result?'Пройти ещё раз':'Начать упражнение'}</button></article>`;}).join('')}</div><h2 class="section-title">База знаний команды</h2><div class="knowledge-grid">${KNOWLEDGE.map(k=>`<button class="knowledge-card" onclick="showKnowledge('${k.id}')">${ic('book')}<div><h3>${k.title}</h3><p>Демонстрационный стандарт · административный процесс</p></div></button>`).join('')}</div><section class="panel panel-pad space-top"><h2>От упражнения к работе</h2><ul class="report-list"><li>${ic('phone')}<span>Разобрать исходное обращение с сотрудником.</span></li><li>${ic('book')}<span>Пройти подходящее упражнение и обсудить ошибку.</span></li><li>${ic('check')}<span>Проверить новое обращение по тому же критерию и зафиксировать наблюдение.</span></li><li>${ic('chart')}<span>Изменение конверсии оценивать по отдельной сопоставимой выборке, а не по факту прохождения теста.</span></li></ul></section>`;}
function showKnowledge(id){const k=KNOWLEDGE.find(x=>x.id===id);showModal(k.title,`<span class="badge">Демо-стандарт / v1</span><p>${k.text}</p><div class="demo-note">В рабочем продукте документ утверждает ответственное лицо клиники. Этот пример не является реальным внутренним регламентом.</div>`);}
function startLesson(id){quizState={id,index:0,score:0,selected:null};drawQuiz();}
function drawQuiz(){const s=quizState,l=LESSONS[s.id],q=l.questions[s.index];showModal(l.title,`<span class="badge">${selectedStaff} · вопрос ${s.index+1} из ${l.questions.length}</span><p>${q.q}</p>${q.options.map((option,i)=>`<button class="quiz-option ${s.selected===i?(i===q.correct?'correct':'wrong'):''}" ${s.selected!==null?'disabled':''} onclick="answerQuiz(${i})"><span>${i+1}</span>${option}</button>`).join('')}${s.selected!==null?`<div class="answer-note"><strong>${s.selected===q.correct?'Верно.':'Нужно разобрать.'}</strong> ${q.why}</div>`:''}`,`<button class="btn" onclick="closeModal()">Закрыть</button>${s.selected!==null?`<button class="btn primary" onclick="nextQuiz()">${s.index===l.questions.length-1?'Завершить упражнение':'Следующий вопрос'} ${ic('arrow')}</button>`:''}`);}
function answerQuiz(value){if(quizState.selected!==null)return;quizState.selected=value;if(value===LESSONS[quizState.id].questions[quizState.index].correct)quizState.score++;drawQuiz();}
function nextQuiz(){const s=quizState;if(s.selected===null)return;if(s.index<LESSONS[s.id].questions.length-1){s.index++;s.selected=null;drawQuiz();return;}data().lessons[selectedStaff]??={};const prev=data().lessons[selectedStaff][s.id];data().lessons[selectedStaff][s.id]={score:s.score,passed:s.score===2,attempts:(prev?.attempts||0)+1};logEvent(`${selectedStaff}: упражнение «${LESSONS[s.id].title}», результат ${s.score}/2`,'book');closeModal();render();toast(s.score===2?'Упражнение пройдено. Следующий шаг - проверка в работе.':'Упражнение завершено. Можно разобрать ответы и повторить.');}
function carePage(){const rows=data().care;return heading('Сопровождение между визитами.','Получение инструкции, вопросы, контрольные контакты и обратная связь. Медицинское содержание задаёт клиника.')+`<section class="metrics">${metric('Открытых ситуаций',rows.filter(x=>!x.closed).length,'Сопровождение по модельным правилам','users')}${metric('Получение подтверждено',rows.filter(x=>x.ack).length,'Не означает медицинскую готовность','check')}${metric('Вопросов специалисту',rows.filter(x=>x.question&&!x.closed).length,'Требуется отдельный ответ','alert')}${metric('Закрыто сопровождений',rows.filter(x=>x.closed).length,'По отмеченным шагам демо','shield',true)}</section><section class="panel"><div class="panel-head"><h2>${clinic==='endo'?'Подготовка и контакт после исследования':'Контрольные визиты и этапы лечения'}</h2><span class="badge">Демо-шаблоны</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Пациент / ситуация</th><th>Ответственный</th><th>Получение</th><th>Вопросы</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${x.patient}</strong><small>${x.kind} · ${x.due}</small></td><td>${x.assigned}</td><td><span class="badge ${x.ack?'green':'neutral'}">${x.ack?'Подтверждено':x.sent?'Доставлено':'Не отмечено'}</span></td><td><span class="badge ${x.question?'orange':'green'}">${x.closed?'Завершено':x.question?'Нужен ответ':'Нет открытых вопросов'}</span></td><td><button class="btn sm" onclick="openCare('${x.id}')">Открыть ${ic('arrow')}</button></td></tr>`).join('')}</tbody></table></div></section><h2 class="section-title">Обратная связь пациентов</h2><section class="panel">${data().tickets.map(t=>`<article class="signal"><span class="signal-mark ${t.status==='closed'?'green':''}">${ic('note')}</span><div class="signal-body"><h3>${t.title}</h3><p>${t.patient} · ответственный ${t.owner}</p></div><div class="signal-end"><span class="badge ${t.status==='closed'?'green':'orange'}">${t.status==='closed'?'Закрыто':'Проверить'}</span>${t.status!=='closed'?`<button class="link" onclick="closeTicket('${t.id}')">Зафиксировать решение ${ic('check')}</button>`:''}</div></article>`).join('')}</section>`;}
function openCare(id){const x=data().care.find(x=>x.id===id);showSuiteDrawer('care',id,'Сопровождение / '+id,`<span class="badge ${x.closed?'green':'neutral'}">${x.closed?'Сопровождение завершено':'Открыто'}</span><h2 id="drawerTitle">${x.kind}</h2><p>${x.patient} · ${x.assigned} · ${x.due}. Полностью вымышленная ситуация.</p><div class="demo-note">${clinic==='endo'?'Вместо медицинской инструкции здесь показан её жизненный цикл: утверждённый клиникой шаблон → получение → вопросы → ответ специалиста.':'Контрольный визит или следующий этап определяет врач. Модуль организует административное сопровождение.'}</div><div class="drawer-section"><h3>Шаги сопровождения</h3>${[['sent','Получение инструкции / приглашения отмечено'],['ack','Пациент подтвердил получение'],['question','Есть вопрос медицинскому специалисту']].map(([k,t])=>`<label style="display:flex;gap:10px;font-size:11px;margin:16px 0;align-items:flex-start"><input type="checkbox" ${x[k]?'checked':''} ${x.closed?'disabled':''} onchange="toggleCare('${id}','${k}',this.checked)">${t}</label>`).join('')}<p class="method">Подтверждение получения не равно подтверждению медицинской готовности.</p><div class="actions space-top">${x.question&&!x.escalated?`<button class="btn primary" onclick="escalateCare('${id}')">Передать вопрос специалисту в демо</button>`:''}${x.question&&x.escalated?`<button class="btn primary" onclick="resolveCareQuestion('${id}')">Смоделировать ответ специалиста</button>`:''}${!x.closed?`<button class="btn" onclick="finishCare('${id}')">Завершить сопровождение</button>`:''}</div></div><div class="drawer-section"><h3>Что показываем пациенту</h3><div class="call-snippet">«Для вашего визита действует инструкция клиники. Подтвердите, пожалуйста, получение. Если остались вопросы, передадим их специалисту».</div><p class="method">Сообщения не отправляются. Текст - пример административной коммуникации без медицинских назначений.</p></div>${x.notes.length?`<div class="drawer-section"><h3>История</h3>${x.notes.map(n=>`<div class="note-card">${esc(n)}</div>`).join('')}</div>`:''}`);}
function toggleCare(id,key,value){const x=data().care.find(x=>x.id===id);if(x.closed)return;if(key==='ack'&&value&&!x.sent){toast('Сначала отметьте получение инструкции / приглашения');openCare(id);return;}if(key==='sent'&&!value)x.ack=false;x[key]=value;if(key==='question'&&value)x.escalated=false;persist();openCare(id);}
function escalateCare(id){const x=data().care.find(x=>x.id===id);x.escalated=true;x.notes.push('27 окт · Вопрос передан ответственному медицинскому специалисту в демо');createManagerTask('care',id,'Организовать ответ специалиста для '+x.patient,x.assigned);logEvent(`${id}: создана задача по вопросу пациента`,'shield');render();openCare(id);}
function resolveCareQuestion(id){const x=data().care.find(x=>x.id===id);if(!x.escalated)return;x.question=false;x.notes.push('27 окт · В модели отмечено получение ответа специалиста; медицинский текст не генерируется');data().managerTasks.filter(t=>t.kind==='care'&&t.target===id).forEach(t=>t.state='done');logEvent(`${id}: ответ специалиста отмечен в демо`,'check');render();openCare(id);}
function finishCare(id){const x=data().care.find(x=>x.id===id);if(!x.sent||!x.ack||x.question){toast('Подтвердите получение и закройте открытые вопросы');return;}x.closed=true;x.notes.push('27 окт · Административное сопровождение завершено');logEvent(`${id}: завершено сопровождение ${x.patient}`,'check');render();openCare(id);}
function closeTicket(id){const t=data().tickets.find(x=>x.id===id);showModal('Зафиксировать решение обращения',`<p>${t.title} · ${t.patient}</p><div class="field"><label for="ticketResolution">Что сделано</label><textarea id="ticketResolution" maxlength="500" placeholder="Например: связались, уточнили вопрос и договорились о следующем шаге"></textarea></div>`,`<button class="btn" onclick="closeModal()">Назад</button><button class="btn primary" onclick="confirmTicket('${id}')">Сохранить решение в демо</button>`);}
function confirmTicket(id){const t=data().tickets.find(x=>x.id===id),v=document.getElementById('ticketResolution').value.trim();if(!v){toast('Опишите выполненное действие');return;}t.status='closed';t.resolution=v;logEvent(`${id}: обращение закрыто. ${v}`,'check');closeModal();render();toast('Решение сохранено');}
function qualityPage(){const checks=qualityChecks(),ok=checks.filter(x=>x.ok).length,score=percent(ok,checks.length),f=financials();return heading('Доверие к цифрам начинается с проверки.','Здесь видно, какие источники смоделированы, чего не хватает и почему некоторые выводы пока недоступны.')+`<div class="split"><section class="panel panel-pad" style="display:flex;gap:25px;align-items:center"><div><div class="score-ring" style="--score:${score}%"><span>${score}%</span></div><span class="tiny-label" style="text-align:center">Проверок пройдено</span></div><div><h2>${ok} из ${checks.length} проверок</h2><p class="method">Это доля выполненных проверок модели, а не вероятность достоверности всех данных.</p><button class="btn text" onclick="showDataRules()">Определения показателей ${ic('arrow')}</button></div></section><section class="panel panel-pad"><h2>Что пока нельзя утверждать</h2><p class="method">${f.complete?'Расходы в модели заполнены. Операционный результат всё ещё промежуточный, месяц не закрыт.':'Полный маржинальный доход и операционный результат не рассчитываются без подтверждённых прямых расходов.'}</p><p class="method">Демо не подключается к МИС, телефонии и бухгалтерии. Кнопки ниже моделируют работу с данными.</p></section></div><h2 class="section-title">Источники демонстрационной модели</h2><div class="quality-grid">${[['clinic','МИС / расписание','Смены, визиты, услуги, планы лечения. Источник факта оказания.'],['phone','Обращения / телефония','Причины обращений, результаты контактов, демо-разборы разговоров.'],['money','Учёт / оплаты и расходы','Оплаты по услугам, прямые расходы и модель постоянных затрат.']].map(([icon,t,desc])=>`<article class="source-card"><span class="source-icon">${ic(icon)}</span><h3>${t}</h3><p>${desc}</p><span class="badge neutral">Смоделировано · интеграции нет</span></article>`).join('')}</div><section class="panel space-top"><div class="panel-head"><h2>Проверки и расхождения</h2><span class="badge">${checks.length-ok} требуют внимания</span></div>${checks.map(q=>`<article class="quality-check"><span class="signal-mark ${q.ok?'green':''}">${ic(q.ok?'check':'alert')}</span><div><h3>${q.title}</h3><p>${q.desc}</p>${!q.ok?`<div class="actions"><button class="btn sm" onclick="resolveQuality('${q.id}')">${q.action}</button><button class="btn sm" onclick="createManagerTask('quality','${q.id}','${q.title}','Анна')">Создать задачу</button></div>`:''}</div><span class="badge ${q.ok?'green':'orange'}">${q.ok?'Пройдено':'Проверить'}</span></article>`).join('')}</section><section class="panel panel-pad space-top"><h2>Единые определения</h2>${[['Запись','Согласованное время. Не означает состоявшийся визит.'],['Оказанная услуга','Подтверждённый факт выполнения. Формирует начисленную выручку.'],['Оплата','Подтверждённое поступление. Не подменяет дату оказания услуги.'],['Маржинальный доход','Выручка за оказанные услуги минус согласованные прямые расходы.'],['Операционный результат','Маржинальный доход минус заданные постоянные расходы, до налогов.']].map(([t,d])=>`<div class="resource-row"><strong style="font-weight:550;min-width:145px">${t}</strong><span style="color:#7b8c71;font-size:10px">${d}</span></div>`).join('')}</section>`;}
function resolveQuality(id){if(id==='cost'){const s=data().services.find(s=>unitCost(s)===null);if(s)fillMissingCost(s.id);return;}if(!['visits','sync'].includes(id))return;data().quality[id]=true;data().managerTasks.filter(t=>t.kind==='quality'&&t.target===id).forEach(t=>t.state='done');logEvent(id==='visits'?'В демо зафиксирована сверка визитов: выбран факт МИС по единому определению.':'Смоделировано обновление статусов финансового источника.','shield');render();toast(id==='visits'?'Сверка зафиксирована в модели':'Обновление источника смоделировано');}
function showDataRules(){showModal('Как связаны данные',`<p>Выручка считается по подтверждённым оказанным услугам, оплаты - по отдельным событиям поступления. Полная стоимость плана остаётся планом.</p><div class="formula-box"><strong>В модели:</strong><br>${data().monthLedger.length} базовых записей услуг<br>${data().plans.length} планов лечения<br>${data().calls.length} вымышленных разговоров<br>${data().care.length} ситуаций сопровождения</div><p>Для рабочего продукта потребуются согласованные идентификаторы, правила сверки, доступы и фактические источники. В этом прототипе они моделируются.</p>`);}
function resultsPage(){const pc=planCounts(),f=financials();return resultsBasePage()+`<h2 class="section-title">Результаты сопровождения и команды</h2><section class="metrics wide-metrics">${metric('Оказано по планам',money(pc.done),'Часть общей выручки модели','note')}${metric('Оплачено по планам',money(pc.paid),'Часть общих оплат модели','money')}${metric('Разобрано разговоров',data().calls.filter(c=>c.reviewed).length+'<span class="unit"> / 12</span>','Работа с демонстрационной выборкой','phone')}${metric('Закрыто сопровождений',data().care.filter(c=>c.closed).length,'Получение и вопросы отработаны','check',true)}</section><section class="panel panel-pad"><h2>Журнал действий</h2><div class="sub">Подтверждённые действия этой демонстрации. Значения сохраняются в текущем браузере.</div>${activityMarkup(15)}</section>${role==='owner'?`<section class="panel panel-pad space-top"><h2>Рамка оценки пилота</h2><ul class="report-list"><li>${ic('chart')}<span>Сравнивать одинаковые услуги и периоды с учётом смен, цен и рекламной нагрузки.</span></li><li>${ic('users')}<span>Разделять найденные ситуации, выполненные действия, записи, визиты и оплаты.</span></li><li>${ic('money')}<span>Дополнительные оплаты не считать автоматически дополнительной прибылью.</span></li><li>${ic('shield')}<span>Кейс пилота строить на фактических событиях и согласованных источниках. Демонстрационные ${money(f.revenue)} не являются результатом реальной клиники.</span></li></ul></section>`:''}`;}
function pilotPage(){const modules=[['assistant','spark','Ассистент руководителя','Сводки, вопросы по данным и конкретные следующие шаги.'],['overview','overview','Ежедневный помощник','Правила по демо-данным, приоритеты и следующий шаг.'],['schedule','calendar','Загрузка и спрос','Расписание, окна, причины несостоявшихся записей, ресурсы.'],['patients','users','Обращения','Назначение, контакт, запись, факт визита и оплата.'],['plans','note','Координатор лечения','Решение пациента, этапы, медицинское согласие и контакты.'],['economics','money','Экономика','Прямые расходы, операционный результат, оплаты и сценарии.'],['team','phone','Качество команды','Демо-диалоги, разборы и связанные задачи.'],['training','book','Практика и знания','Короткие упражнения, результаты и проверка применения.'],['care','shield','Сопровождение','Получение инструкций, вопросы, специалист и обратная связь.'],['quality','shield','Качество данных','Источники, расхождения, полнота расходов и определения.']];return heading('Полная картина продукта.','Расширенный демонстрационный прототип NNOV.RU. Все модули работают на одной вымышленной модели.',`<button class="btn primary" onclick="startTour()">${ic('play')}Показать все модули</button>`)+`<section class="panel suite-hero"><div class="eyebrow">NNOV Клиника / v0.4</div><h2>От управленческого сигнала до действия команды и проверяемого результата.</h2><p>Выберите клинику и рабочее место. Можно пройти путь администратора, координатора или руководителя, затем сравнить изменения в расписании, задачах и экономике.</p><div class="pill-row"><span class="chip">2 клиники-сценария</span><span class="chip">3 рабочих места</span><span class="chip">13 разделов</span><span class="chip">Прогресс в браузере</span></div></section><h2 class="section-title">Что можно попробовать</h2><div class="module-grid">${modules.map(([id,icon,t,d])=>`<article class="module">${ic(icon)}<h3>${t}</h3><p>${d}</p><div class="module-foot"><span class="badge green">Интерактивное демо</span><button class="btn text" onclick="navigate('${id}')">Открыть ${ic('arrow')}</button></div></article>`).join('')}</div><div class="split space-top"><section class="panel panel-pad"><h2>Что моделируется</h2><ul class="checklist">${['Данные услуг, оплат, затрат и планов','Сводка по детерминированным правилам','Согласование времени и выполнение этапов','Разборы и упражнения для сотрудников','Обновление источников и сверка показателей'].map(x=>`<li>${ic('check')}<span>${x}</span></li>`).join('')}</ul></section><section class="panel panel-pad"><h2>Для рабочего продукта</h2><p class="method">Нужны реальные интеграции, серверное хранение, роли доступа, журнал действий, утверждённые клиникой правила и документы. Выбор рабочего места здесь меняет интерфейс и не является системой защиты данных.</p><p class="method">В демо нет фактических звонков, рассылок, генерации лечения, оформления согласий или подключения к медицинским системам.</p><div class="actions space-top"><button class="btn" onclick="exportDemo()">${ic('down')}Скачать демо-данные JSON</button><button class="btn" onclick="resetDemo()">${ic('reset')}Сбросить демо</button></div></section></div><h2 class="section-title">Предлагаемая проверка на пилоте</h2><div class="steps">${[['01','Согласовать процесс','Один филиал, определения показателей, текущая МИС и ответственные.'],['02','Подтвердить источники','Связать обращения, визиты, услуги и оплаты; проверить расходы.'],['03','Проверить действия','Работать по очередям и этапам, фиксировать фактические результаты.'],['04','Оценить эффект','Сопоставить периоды и трудозатраты, решить о развитии продукта.']].map(([n,t,d])=>`<article class="step"><span class="step-number">${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><p class="presentation-note">Состав пилота, цена и сроки требуют согласования. Экономический эффект и маржинальность бизнеса не подтверждены демо-моделью.</p>`;}
const SUITE_TOUR=[
 {view:'overview',title:'01. Руководитель видит главное.',text:'Обзор связывает пациентов, расписание и экономику. Каждый приоритет содержит основание и понятный следующий шаг.',value:()=>utilization().free+' ч',lead:'Свободное время сегодня',action:'Разобрать обращение',code:"closeModal();openItem('D-104')"},
 {view:'assistant',title:'02. Ассистент объясняет следующий шаг.',text:'Посмотрите сводку, задайте вопрос о прибыли или назначении задачи. Из ответа можно перейти к нужной карточке. После действий рекомендации обновятся.',value:()=>assistantPriorities().length,lead:'Текущих административных фокуса',action:'Открыть чат',code:"closeModal();navigate('assistant')"},
 {view:'schedule',title:'03. Загрузка объясняется спросом.',text:'Свободные окна сопоставлены с обращениями. Отдельно видны причины отказов, ресурсы и назначенные этапы лечения.',value:()=>utilization().pct+'%',lead:'Загрузка демо-расписания'},
 {view:'plans',title:'04. План получает следующий шаг.',text:'Откройте P-101: сохраните решение пациента, назначьте этап, отметьте наличие согласия, выполнение услуги и оплату.',value:()=>planCounts().active,lead:'Планов на сопровождении',action:'Попробовать план',code:"closeModal();openPlan('P-101')"},
 {view:'economics',title:'05. Прибыль начинается с расходов.',text:'Полный результат недоступен, пока не заполнены материалы. Введите расход в демо, затем измените параметры сценария цен и затрат.',value:()=>financials().coverage+'%',lead:'Выручки с известными прямыми затратами'},
 {view:'team',title:'06. Разбор превращается в задачу.',text:'Разберите вымышленный диалог, создайте задачу и откройте связанное упражнение для сотрудника.',value:()=>data().calls.filter(c=>!c.reviewed).length,lead:'Разговоров требуют разбора',action:'Открыть разбор',code:"closeModal();openCall('C-201')"},
 {view:'training',title:'07. Обучение связано с практикой.',text:'Два коротких упражнения проверяют административные навыки. После прохождения нужен отдельный разбор применения в работе.',value:()=> '2 × 2',lead:'Упражнения и вопросы'},
 {view:'quality',title:'08. Пробелы в данных видны.',text:'Смоделируйте сверку визитов, заполнение расходов и обновление источника. Показатели проверок изменятся.',value:()=>qualityChecks().filter(q=>q.ok).length+'/4',lead:'Проверок модели пройдено'},
 {view:'results',title:'09. Действия оставляют след.',text:'Отчёт разделяет записи, визиты и оплаты. Журнал сохраняет действия, а демо-прогресс останется после перезагрузки страницы.',value:()=>money(counts().receipts),lead:'Оплаты из возвращённых обращений'}
];
function startTour(){role='owner';closeDrawer(false);closeModal();tourStep=0;showTour();}
function showTour(){const t=SUITE_TOUR[tourStep];view=t.view;filter='all';render();showModal(t.title,`<div class="tour-stepper">${SUITE_TOUR.map((_,i)=>`<i class="${i<=tourStep?'active':''}"></i>`).join('')}</div><p>${t.text}</p><div class="tour-visual"><span class="num">${t.value()}</span><div><strong>${t.lead}</strong><p>Все показатели демонстрационные</p></div></div>`,`<button class="btn" onclick="${tourStep?'tourStep--;showTour()':'closeModal()'}">${tourStep?'Назад':'Закрыть'}</button><div class="actions">${t.action?`<button class="btn" onclick="${t.code}">${t.action}</button>`:''}<button class="btn primary" onclick="${tourStep===SUITE_TOUR.length-1?'closeModal()':'tourStep++;showTour()'}">${tourStep===SUITE_TOUR.length-1?'Открыть результаты':'Дальше'} ${ic('arrow')}</button></div>`);}
function showAbout(){showModal('NNOV Клиника. Расширенный прототип.',`<p>Два сценария клиник, три рабочих места и связанные модули управления. Данные, пациенты, разговоры, планы, расходы и результаты полностью вымышлены.</p><div class="formula-box"><strong>Сохранение прогресса</strong><br>${storageAvailable?'Изменения сохраняются локально в этом браузере. Можно перезагрузить страницу и продолжить.':'Хранилище браузера недоступно. Изменения сохраняются только в текущей вкладке.'} Данные не отправляются на сервер клиники.</div><p>Интеграции, ИИ, коммуникации и медицинские документы моделируются. Демо-ассистент отвечает по правилам на смоделированных данных, хранит диалог и обновляет сводки при изменениях. Ролевой переключатель показывает разные интерфейсы и не заменяет серверные права доступа.</p>`,`<button class="btn" onclick="resetDemo()">${ic('reset')}Сбросить демо</button><button class="btn primary" onclick="closeModal();startTour()">${ic('play')}Сценарий презентации</button>`);}
function resetDemo(){showModal('Вернуть исходное демо?',`<p>Будут сброшены изменения в обеих клиниках: задачи, записи, решения по планам, оплаты, упражнения и проверки данных. Исходные демонстрационные примеры восстановятся.</p>`,`<button class="btn" onclick="closeModal()">Отмена</button><button class="btn primary" onclick="confirmReset()">Сбросить обе клиники</button>`);}
function confirmReset(){DB.implant=suiteSeed('implant');DB.endo=suiteSeed('endo');role='owner';view='overview';filter='all';query='';financeFocus='all';quizState=null;closeDrawer(false);closeModal();render();toast('Обе клиники возвращены к исходному демо');}
function downloadText(name,text,type='text/plain;charset=utf-8'){const blob=new Blob(['\ufeff'+text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportReport(){const c=counts(),u=utilization(),f=financials(),p=planCounts();downloadText('NNOV_Clinic_demo_report.txt',`NNOV Клиника - демонстрационная сводка v0.4\n${cfg().name} / вымышленные данные\nДемо-день 27 октября 2026\n\nСегодня занято ${u.occupied}/${u.total} ч (${u.pct}%).\nИз обращений записано: ${c.booked}. Состоялось визитов: ${c.attended}. Получено: ${money(c.receipts)}.\n\nПланы: ${data().plans.length}; активных ${p.active}; на паузе ${p.paused}.\nОказано по планам: ${money(p.done)}. Оплачено по планам: ${money(p.paid)}.\n\nМодель месяца 1–27 октября:\nОказано услуг: ${f.services}.\nНачисленная выручка: ${money(f.revenue)}.\nПолучено оплат: ${money(f.paid)}.\nРасходами покрыто ${f.coverage}% выручки.\nМаржинальный доход: ${f.complete?money(f.contribution):'Нет полных данных'}.\nОперационный результат до налогов: ${f.complete?money(f.contribution-f.fixed):'Нет полных данных'}.\n\nКачество: ${qualityChecks().filter(x=>x.ok).length}/4 проверок пройдено.\n\nЖурнал:\n${data().events.map(x=>x.time+' | '+x.text).join('\n')}\n\nЭто демонстрация, не отчёт реальной клиники. Оплаты не равны прибыли. Эффект продукта не доказан этой моделью.`);toast('Демо-сводка скачана');}
function exportFinance(){const rows=[['ID','Дата октября','Услуга','Количество','Оказано ₽','Оплачено ₽','Прямые расходы ₽','Основание'],...allLedger().map(x=>[x.id,x.day,svc(x.service).name,x.qty,x.amount,x.paid,unitCost(svc(x.service))===null?'':unitCost(svc(x.service))*x.qty,x.source])];downloadText('NNOV_Clinic_demo_finance.csv',rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Демонстрационный расчёт скачан');}
function exportDemo(){downloadText('NNOV_Clinic_demo_data.json',JSON.stringify({notice:'Полностью вымышленные данные. Не результат реальной клиники.',schema:2,db:DB},null,2),'application/json;charset=utf-8');toast('Демо-данные скачаны');}
